import { defineConfig } from 'vitest/config'
import { loadEnv } from 'vite'
import react from '@vitejs/plugin-react'

// Generated By Claude -- Subject To Errors

// https://vite.dev/config/
export default defineConfig(({ command, mode }) => {
  // VITE_API_URL is baked into the bundle at build time. A production build
  // without it would quietly call http://localhost:3000 from users' browsers,
  // so stop the build instead. Reads both .env files and real environment
  // variables (e.g. ones set in the Vercel dashboard).
  if (command === 'build' && mode === 'production') {
    const env = loadEnv(mode, process.cwd());
    if (!env.VITE_API_URL) {
      throw new Error(
        'VITE_API_URL is not set. Set it to the deployed backend URL ' +
        '(e.g. in the Vercel project settings) before building for production.'
      );
    }
  }

  return {
    plugins: [react()],
    test: {
      environment: 'jsdom',
      setupFiles: './src/tests/setup.ts',
      clearMocks: true,
      restoreMocks: true,
    },
  };
});
